#include <iostream>
#include <string>

std::string hideCardNumber(const std::string& card) {
    std::size_t hidden = card.size() > 4 ? card.size() - 4 : 0;
    return std::string(hidden, '*') + card.substr(hidden);
}

int main() {
    std::string card;
    std::cin >> card;
    std::cout << hideCardNumber(card) << "\n";
    return 0;
}

