go.solution:
package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func hideCardNumber(card string) string {
	hidden := len(card) - 4
	if hidden < 0 {
		hidden = 0
	}
	return strings.Repeat("*", hidden) + card[hidden:]
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	card := strings.TrimSpace(scanner.Text())
	fmt.Println(hideCardNumber(card))
}

